        dataset_id, tenant_id, id, version, name, description, report_type, schedule_expression, concurrency_policy, display_order, tier, applicable_jurisdiction, regulatory_book_type, cut_kind_code
    )
    values
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Data Quality Completeness', 'Validates all required market data, reference data, and trade data is present across the entity. Flags gaps in instrument codes, missing curve pillars, stale fixings, and orphaned trades. Runs early so downstream analytics have a clean data baseline.', 'risk', '0 5 * * 1-5', 'skip', 5, 'common', null, null, null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'System Health', 'Monitors service availability, NATS message latency, database connection pool saturation, and per-service error rates. Produces a traffic-light dashboard: green (all healthy), amber (degraded), red (down). Alerts on sustained error-rate spikes above 5%.', 'risk', '30 5 * * 1-5', 'skip', 10, 'common', null, null, null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Audit Trail Summary', 'Daily summary of all create, update, and delete operations across all domain entities for the entity. Broken down by service, actor, and change reason category. Supports SOX and SOC 2 compliance requirements for change logging.', 'risk', '0 6 * * 1-5', 'skip', 15, 'common', null, null, null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Leverage Ratio', 'Computes the Basel III leverage ratio: Tier 1 capital divided by total exposure measure (on- and off-balance sheet, derivatives, SFTs). Alerts if the ratio approaches the 3% minimum threshold. Required for all regulated entities under CRR/Basel III pillar 2.', 'risk', '0 6 * * 1-5', 'skip', 25, 'regulatory', null, null, null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Liquidity Coverage', 'Liquidity Coverage Ratio (LCR): High-Quality Liquid Assets divided by net cash outflows over a 30-day stress horizon. Flags when HQLA buffer drops below 100% minimum. Required under Basel III for all regulated deposit-taking and investment firms.', 'risk', '0 7 * * 1-5', 'skip', 35, 'regulatory', null, null, null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Large Exposures', 'Monitors single-counterparty exposure concentration against the 25% of Tier 1 capital regulatory limit. Aggregates across all netting sets, SFTs, and indirect exposures for each legal entity counterparty. Produces breach alerts and a top-20 concentration report.', 'risk', '0 7 * * 1-5', 'skip', 40, 'regulatory', null, null, null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Group Consolidated Exposure', 'Aggregate exposure across all subsidiaries by asset class, currency, and counterparty. Eliminates intercompany positions per IFRS 10 consolidation rules. Provides the single group-wide risk view for the board and regulators. Holding company only.', 'risk', '0 8 * * 1-5', 'skip', 60, 'strategic', null, null, null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Board Risk Dashboard', 'One-page executive summary for the board risk committee: group VaR (99% 1-day), total exposure by asset class, consolidated P&L, capital ratios (CET1, leverage, LCR), top 10 counterparty exposures, and month-on-month trend arrows. Holding company only.', 'risk', '0 8 * * 1-5', 'skip', 65, 'strategic', null, null, null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Cross-Entity Counterparty Concentration', 'Aggregates single-name counterparty exposure across all legal entities in the group. Flags names exceeding 25% of consolidated Tier 1 capital. Identifies hidden concentration where individual subsidiary exposures appear within limits but group aggregate breaches the threshold. Holding company only.', 'risk', '0 8 * * 1-5', 'skip', 70, 'strategic', null, null, null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Intercompany Exposure Matrix', 'Matrix of exposures between all group entities for consolidation elimination. Identifies circular funding, transfer pricing mismatches, and netting inefficiencies across the group. Monthly cadence (not daily — intercompany positions churn slowly). Holding company only.', 'risk', '0 6 1 * *', 'skip', 75, 'strategic', null, null, null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice Rho Ladder', 'The rate value change at each bucket when the curve moves by one shift, discount and projection effects kept apart. It reads the live cut, so a reader questions the shape of the rate risk while the day is still moving. The shift is a setting of the sensitivity document, so the definition states the scope and the cut and never the size.', 'risk', '*/30 8-17 * * 1-5', 'skip', 200, 'trading', null, null, 'LIVE'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice Rho Ladder (EOD)', 'The rate value change at each bucket at the close, discount and projection effects kept apart, priced from the day''s authorised end of day cut. It is the rate risk statement of record, and a later run of the intraday definition never replaces it.', 'risk', '0 18 * * 1-5', 'skip', 201, 'trading', null, null, 'EOD'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice Gamma Ladder', 'The second-order value change in one rate factor at each bucket, taken from the gamma column the engine writes when the sensitivity document switches the second order on. The figure is money and not a curvature per unit, so a reader compares closes and does not rescale it.', 'risk', '0 18 * * 1-5', 'skip', 205, 'trading', null, null, 'EOD'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice Theta Ladder', 'The value change from moving the clock rather than a market, read from the period the sensitivity document states. Its buckets are periods and not curve tenors or volatilities, so it is a ladder of its own.', 'risk', '0 18 * * 1-5', 'skip', 210, 'trading', null, null, 'EOD'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice Cross-gamma Ladder', 'The curvature between two rate factors of one risk class, read from the rows that carry a second factor. The engine writes those rows inside its sensitivity file rather than in a file of their own, so the report reads the pairs where they land.', 'risk', '0 18 * * 1-5', 'skip', 215, 'trading', null, null, 'EOD'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice ATM Vega Ladder', 'The value change at the at-the-money point of each expiry when volatility moves by the shift the document states. It reads the live cut, so a desk sees the shape of its volatility risk between the closes.', 'risk', '*/30 8-17 * * 1-5', 'skip', 220, 'trading', null, null, 'LIVE'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice ATM Vega Ladder (EOD)', 'The at-the-money volatility value change at each expiry at the close, priced from the day''s authorised end of day cut. It is the volatility statement of record.', 'risk', '0 18 * * 1-5', 'skip', 221, 'trading', null, null, 'EOD'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice Surface Vega Ladder', 'The value change at every configured strike of every expiry, which is the surface shifted with its shape held. The catalogue calls the same computation the .1 Triple. It reads the live cut, so a desk sees the smile between the closes.', 'risk', '*/30 8-17 * * 1-5', 'skip', 225, 'trading', null, null, 'LIVE'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice Surface Vega Ladder (EOD)', 'The value change at every configured strike of every expiry at the close, priced from the day''s authorised end of day cut. It is the full-surface statement of record.', 'risk', '0 18 * * 1-5', 'skip', 226, 'trading', null, null, 'EOD'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice Risk-reversal Vega Ladder', 'The call change minus the put change at each expiry, derived from the surface points of a full-surface run rather than asked of the engine. The catalogue calls it the .1 risk reversal. It reads the live cut.', 'risk', '*/30 8-17 * * 1-5', 'skip', 230, 'trading', null, null, 'LIVE'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice Risk-reversal Vega Ladder (EOD)', 'The call change minus the put change at each expiry at the close, derived from the surface points of a full-surface run. It is the skew statement of record.', 'risk', '0 18 * * 1-5', 'skip', 231, 'trading', null, null, 'EOD'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice Butterfly Vega Ladder', 'The wing curvature at each expiry, being half the call change plus half the put change less the at-the-money point. The catalogue calls it the .1 strangle, and the reader takes the butterfly style the pair is stored with rather than a plain average. It reads the live cut.', 'risk', '*/30 8-17 * * 1-5', 'skip', 235, 'trading', null, null, 'LIVE'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice Butterfly Vega Ladder (EOD)', 'The wing curvature at each expiry at the close, from the same run as the risk reversal. It is the wing statement of record.', 'risk', '0 18 * * 1-5', 'skip', 236, 'trading', null, null, 'EOD'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice DV01 Ladder', 'The money value of one basis point at each curve bucket, converted to par instruments so a reader compares one instrument''s risk against another''s. It reads the par sensitivity column the engine writes.', 'risk', '0 18 * * 1-5', 'skip', 240, 'trading', null, null, 'EOD'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice Delta Ladder', 'The first-order value change for one factor at a time, bucketed by the factor key, and the general reader of the ladder family. Seeded, it states the currency pair spots the sensitivity document bumps; every other ladder here is this reader applied to a different block of that document.', 'risk', '0 18 * * 1-5', 'skip', 245, 'trading', null, null, 'EOD');

